#!/usr/bin/env bash
# Extract the release notes for a given version from a CHANGELOG.md.
# Prints the body of the matching section to stdout.
#
# Usage: extract-release-notes.sh <version> [changelog-path]
#
#   version         Version string without leading v (e.g. 1.2.3)
#   changelog-path  Path to CHANGELOG.md (default: CHANGELOG.md)
#
# ----------------------------------------------------------------------------
# Expected CHANGELOG format
# ----------------------------------------------------------------------------
# Component changelogs are generated by git-cliff using cliff.toml and have
# section headings of the form:
#
#   ## v<version> (<YYYY-MM-DD>)
#
#   ### Features
#   - *(scope)* commit message
#
#   ### Bug Fixes
#   - commit message
#
# System (root) changelogs are maintained by the release-system-pr workflow
# and have section headings of the form:
#
#   ## [<version>] - <YYYY-MM-DD>
#
# Both formats are supported: the extractor matches a heading that contains
# the version string, regardless of brackets or date style.
#
# The section body is everything between that heading (exclusive) and the
# next ## heading (exclusive). Leading and trailing blank lines are stripped.
#
# ----------------------------------------------------------------------------
# Output for GitHub Releases
# ----------------------------------------------------------------------------
# The extracted body is used verbatim as the GitHub Release description. It
# contains the markdown content from the CHANGELOG section (features, bug
# fixes, etc.) as rendered by git-cliff or authored by the release workflow.
# ----------------------------------------------------------------------------

set -euo pipefail

VERSION="${1:?version required}"
CHANGELOG="${2:-CHANGELOG.md}"

if [ ! -f "${CHANGELOG}" ]; then
  echo "::error::${CHANGELOG} not found" >&2
  exit 1
fi

# Match a ## heading that contains the version string (with or without brackets,
# with or without a leading v). Stop at the next ## heading.
NOTES=$(awk \
  -v ver="${VERSION}" \
  '/^## .*v?'"${VERSION//./\\.}"'[^0-9]/{found=1; next}
   found && /^## /{exit}
   found{print}' \
  "${CHANGELOG}" \
  | sed -e '/./,$!d' -e 's/[[:space:]]*$//')

if [ -z "${NOTES}" ]; then
  echo "::error::No release notes found for version ${VERSION} in ${CHANGELOG}" >&2
  exit 1
fi

echo "${NOTES}"
